'use client';

/**
 * The plan picker shared by §33's Modules, Features and Limits screens.
 *
 * ## Why these three screens need one
 *
 * §33 names Modules, Features and Limits as screens. The API has no collection behind any of them:
 * they are `PUT /plans/{id}/modules`, `…/features` and `…/limits` — sub-resources of a plan, edited
 * through the plan that owns them. There is no "all modules across all plans" to list, and there
 * could not be: a module key means nothing on its own, only whether *this plan* includes it.
 *
 * So each screen asks which plan first, exactly as Sections asks which class. That is not a
 * workaround for a missing endpoint — it is the question the endpoint answers.
 *
 * The chosen plan lives in the URL (`?plan=3`), so the screen survives a reload and can be linked.
 *
 * ## Two requests, and both are needed
 *
 * `/plans` fills the picker. `/plans/{id}` returns that plan **with its modules, features, limits and
 * prices included** (`plans.service.js:84` `DETAIL_INCLUDE`), which is what each screen renders.
 * `/plans/catalogue` supplies the vocabulary for Modules and Limits — §11's twenty module keys and
 * eight limit keys with their units — so those two screens can show what a plan *could* include and
 * not merely what it does.
 *
 * There is no *feature* vocabulary anywhere in the codebase, and `plan_features` carries its own
 * `feature_key` and `name` per row — so the Features screen is a free list rather than a grid over a
 * fixed set. That asymmetry is real and is why the three screens are three files rather than one
 * with a switch. It still reads the catalogue, for one narrow thing: `featureItem.module_key` is
 * `valid(...MODULE_LIST)`, so the module a feature is grouped under does come from the fixed twenty.
 */

import { useRouter, useSearchParams } from 'next/navigation';
import { useEffect, useState } from 'react';

import { ApiError, api } from '@/lib/apiClient';
import { useCollection, EXPLAINED_CODES } from '@/lib/useCollection';
import type { Refusal } from '@/lib/useCollection';
import { SelectField } from '@/components/form';
import { EmptyNotice, ErrorNotice, LoadingBlock, RefusalNotice } from '@/components/table';

export interface PlanRow {
  id: number;
  name: string;
  code: string;
  status: string;
}

export interface PlanModule {
  id: number;
  module_key: string;
  is_enabled: boolean;
  /**
   * Free-form per-module configuration.
   *
   * Nothing in the entitlement chain reads it — `hasModule()` resolves from `is_enabled` alone, and
   * the column's own comment says it is stored for the Plan Builder. It is typed and carried anyway,
   * because `PUT /plans/:id/modules` replaces the whole set: an editor that sent every module back
   * without this field would silently empty it on save.
   */
  settings: Record<string, unknown> | null;
}

export interface PlanFeature {
  id: number;
  feature_key: string;
  name: string | null;
  is_enabled: boolean;
  value: unknown;
  module_key: string | null;
  display_order: number | null;
}

export interface PlanLimit {
  id: number;
  limit_key: string;
  limit_type: string;
  limit_value: number | null;
  unit: string | null;
  allow_overage: boolean;
  overage_unit_amount: string | number | null;
}

/**
 * One `plan_prices` row — SRS §10.3 (billing cycles) and §10.4 (pricing models).
 *
 * Every money column is `DECIMAL`, and `config/database.js` sets `dialectOptions.decimalNumbers`,
 * so they arrive as JS numbers. The union with `string` is kept for the reason the teachers screen
 * gives for the same shape: one line of configuration decides it, and a type that accepts both
 * cannot be broken by flipping it.
 */
export interface PlanPrice {
  id: number;
  billing_cycle: string;
  cycle_days: number | null;
  pricing_model: string;
  currency: string;
  base_amount: string | number | null;
  unit_amount: string | number | null;
  included_units: number | null;
  tier_min_units: number | null;
  tier_max_units: number | null;
  overage_unit_amount: string | number | null;
  custom_amount: string | number | null;
  custom_notes: string | null;
  setup_fee: string | number | null;
  is_active: boolean;
  is_default: boolean;
  display_order: number | null;
}

export interface PlanDetail extends PlanRow {
  /* The plan's own editable columns — `PATCH /plans/:id`'s field set. */
  description: string | null;
  visibility: string;
  is_recommended: boolean;
  display_order: number;
  trial_days: number;
  grace_period_days: number;
  default_renewal_mode: string;
  tier_rank: number;

  modules: PlanModule[];
  features: PlanFeature[];
  limits: PlanLimit[];
  prices: PlanPrice[];
}

/** `GET /plans/catalogue` — §11's fixed vocabulary. Features are absent from it by design. */
export interface Catalogue {
  modules: { key: string; label: string }[];
  limits: { key: string; label: string; unit: string | null; types: string[] }[];
  /** §10.3. `days` is null for `custom_days` (the length is per price row) and for `one_time`. */
  billingCycles: { cycle: string; days: number | null }[];
  /** §10.4's five models, in the order `constants.js` declares them. */
  pricingModels: string[];
}

/** The plan chosen in the URL, and a setter that keeps it there. */
export function useSelectedPlan(): [string | null, (id: string) => void] {
  const router = useRouter();
  const params = useSearchParams();

  const selected = params.get('plan');

  const select = (id: string) => {
    const next = new URLSearchParams(params.toString());
    if (id) next.set('plan', id);
    else next.delete('plan');
    router.replace(`?${next.toString()}`, { scroll: false });
  };

  return [selected, select];
}

/**
 * Load one plan with everything `DETAIL_INCLUDE` attaches, and optionally the catalogue.
 *
 * Returns `null` for the detail until a plan is chosen, rather than fetching `/plans/undefined`.
 */
export function usePlanDetail(planId: string | null, withCatalogue: boolean) {
  const [detail, setDetail] = useState<PlanDetail | null>(null);
  const [catalogue, setCatalogue] = useState<Catalogue | null>(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [refusal, setRefusal] = useState<Refusal | null>(null);
  const [nonce, setNonce] = useState(0);

  useEffect(() => {
    if (!planId) {
      /*
       * Everything, not only the detail. A load aborted by clearing the choice skips its `finally`, so
       * `loading` stayed true, and a previous plan's error or refusal stayed on screen for no plan.
       */
      setDetail(null);
      setLoading(false);
      setError(null);
      setRefusal(null);
      return undefined;
    }

    const controller = new AbortController();
    setLoading(true);
    setError(null);
    setRefusal(null);

    (async () => {
      try {
        const [plan, cat] = await Promise.all([
          api.get<{ plan: PlanDetail }>(`/plans/${planId}`, { signal: controller.signal }),
          withCatalogue
            ? api.get<Catalogue>('/plans/catalogue', { signal: controller.signal })
            : Promise.resolve(null),
        ]);
        if (controller.signal.aborted) return;
        /* `show` wraps its payload: `{ plan: … }`, unlike the list, which returns rows directly. */
        setDetail(plan.plan);
        if (cat) setCatalogue(cat);
      } catch (caught) {
        if (controller.signal.aborted) return;
        if (caught instanceof ApiError && EXPLAINED_CODES.has(caught.code)) {
          setRefusal({ code: caught.code, message: caught.message });
        } else if (caught instanceof ApiError) {
          setError(caught.message);
        } else if ((caught as Error)?.name !== 'AbortError') {
          setError('Could not reach the server. Check your connection and try again.');
        }
      } finally {
        if (!controller.signal.aborted) setLoading(false);
      }
    })();

    return () => controller.abort();
  }, [planId, withCatalogue, nonce]);

  return { detail, catalogue, loading, error, refusal, reload: () => setNonce((n) => n + 1) };
}

/** The picker itself, plus the states that belong to loading the plan list. */
export function PlanPicker({ selected, onSelect }: { selected: string | null; onSelect: (id: string) => void }) {
  const plans = useCollection<PlanRow>('/plans', { limit: 100 });

  if (plans.refusal) return <RefusalNotice refusal={plans.refusal} />;
  if (plans.error) return <ErrorNotice message={plans.error} onRetry={plans.reload} />;
  if (plans.loading) return <LoadingBlock />;
  if (plans.rows.length === 0) {
    return <EmptyNotice>No plans exist yet. Create one before configuring what it includes.</EmptyNotice>;
  }

  return (
    <div className="mb-5 max-w-sm">
      {/*
        * `SelectField` rather than a hand-rolled label and `<select>`, which is what this was: the
        * wrapper is what carries the error slot, the `aria-describedby` wiring and the one set of
        * control styles every other select in the product uses. There is nothing about this picker
        * that needed its own copy of half of that.
        */}
      <SelectField
        id="plan-picker"
        label="Plan"
        value={selected ?? ''}
        onChange={(event) => onSelect(event.target.value)}
        hint="Modules, features, limits and pricing all belong to one plan, so this is the first question each of those screens asks."
      >
        <option value="">Choose a plan…</option>
        {plans.rows.map((plan) => (
          <option key={plan.id} value={plan.id}>
            {plan.name} ({plan.code})
          </option>
        ))}
      </SelectField>
    </div>
  );
}
